<script setup lang="ts">
import { computed, onScopeDispose, shallowRef, watch } from 'vue'
import { ApiError, errorText, request, session } from '../../api/http'
import type { DailyStatistic, StatisticsOverview } from '../../api/types'
function shanghaiDate(offset = 0) { const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date(Date.now() + offset * 86400000)); const value = (type: string) => parts.find(part => part.type === type)!.value; return `${value('year')}-${value('month')}-${value('day')}` }
const today = shanghaiDate(), from = shallowRef(today.slice(0, 8) + '01'), until = shallowRef(shanghaiDate(1)), overview = shallowRef<StatisticsOverview | null>(null), daily = shallowRef<DailyStatistic[]>([]), loading = shallowRef(false), error = shallowRef(''), reload = shallowRef(0)
const canView = computed(() => session.user.value?.roles.some(role => role === 'ADMIN' || role === 'LEADER') === true)
let scope = new AbortController()
onScopeDispose(() => scope.abort())
function clear() { overview.value = null; daily.value = [] }
function fail(e: unknown) { error.value = errorText(e); if (e instanceof ApiError && [401, 403].includes(e.status)) clear() }
async function load(current = scope) {
  if (!session.token.value || !canView.value) { clear(); return }
  clear(); loading.value = true; error.value = ''
  try {
    const [nextOverview, nextDaily] = await Promise.all([request<StatisticsOverview>(`/api/statistics/overview?from=${from.value}&until=${until.value}`, { signal: current.signal }), request<DailyStatistic[]>(`/api/statistics/daily?from=${from.value}&until=${until.value}`, { signal: current.signal })])
    if (current.signal.aborted) return
    overview.value = nextOverview; daily.value = nextDaily
  } catch (e) { if (!current.signal.aborted) fail(e) }
  finally { if (!current.signal.aborted) loading.value = false }
}
watch([session.token, canView, reload], () => { scope.abort(); scope = new AbortController(); loading.value = false; load(scope) }, { immediate: true, flush: 'sync' })
</script>
<template><div class="page-heading"><div><h1>统计看板</h1><p class="muted">按上海时区统计；结束日期不包含在查询范围内。日报待刷新不等于 0。</p></div><form class="date-filter" @submit.prevent="reload++"><label>开始日期<input v-model="from" type="date" required></label><label>结束日期<input v-model="until" type="date" required></label><button :disabled="loading">查询</button></form></div><p v-if="!canView" class="notice">统计仅向组长和管理员开放。</p><p v-if="error" class="error" role="alert">{{ error }} <button @click="reload++">重试</button></p><p v-if="loading" role="status">正在读取统计…</p><template v-else-if="overview"><section class="metric-grid"><article><span>新增工单</span><strong>{{ overview.totals.createdCount }}</strong></article><article><span>平均响应</span><strong>{{ overview.totals.averageResponseSeconds == null ? '暂无数据' : `${Math.round(overview.totals.averageResponseSeconds)}秒` }}</strong></article><article><span>平均解决</span><strong>{{ overview.totals.averageResolveSeconds == null ? '暂无数据' : `${Math.round(overview.totals.averageResolveSeconds)}秒` }}</strong></article><article><span>SLA达成率</span><strong>{{ overview.slaAchievementRate == null ? '暂无数据' : `${(overview.slaAchievementRate * 100).toFixed(1)}%` }}</strong></article><article><span>超时工单</span><strong>{{ overview.totals.overdueCount }}</strong></article><article><span>AI分类采纳率</span><strong>{{ overview.aiClassificationAcceptanceRate == null ? '暂无数据' : `${(overview.aiClassificationAcceptanceRate * 100).toFixed(1)}%` }}</strong></article></section><section class="panel panel-padding"><h2>每日新增</h2><p class="muted">查询区间：{{ overview.from }} 至 {{ overview.until }}（不含结束日期）。SLA 达成：{{ overview.totals.slaAchieved }}/{{ overview.totals.resolvedSamples }} 个已解决或关闭工单；AI 分类采纳：{{ overview.ai?.acceptedCount ?? 0 }}/{{ overview.ai?.successfulCount ?? 0 }} 次成功分类。客服和组工作量为当前值。</p><p class="muted">数据截点：{{ new Date(overview.asOf).toLocaleString() }}。</p><p v-if="!daily.length" class="muted">暂无数据。</p><table v-else><thead><tr><th>日期</th><th>新增</th><th>状态</th></tr></thead><tbody><tr v-for="item in daily" :key="item.businessDate"><th>{{ item.businessDate }}</th><td>{{ item.createdCount == null ? '待刷新' : item.createdCount }}</td><td>{{ item.requested ? '待重新统计' : item.refreshedAt ? `已刷新 ${new Date(item.refreshedAt).toLocaleString()}` : '统计处理中' }}</td></tr></tbody></table></section><section class="detail-grid"><article class="panel panel-padding"><h2>分类工单数</h2><p v-if="!overview.categories.length" class="muted">暂无数据。</p><ul v-else><li v-for="item in overview.categories" :key="item.categoryId">分类 #{{ item.categoryId }}：{{ item.ticketCount }}</li></ul></article><article class="panel panel-padding"><h2>客服处理中量</h2><p v-if="!overview.agents.length" class="muted">暂无数据。</p><ul v-else><li v-for="item in overview.agents" :key="item.assigneeId">客服 #{{ item.assigneeId }}（组 #{{ item.groupId }}）：{{ item.processingCount }}</li></ul></article><article class="panel panel-padding"><h2>服务组工作量</h2><p v-if="!overview.groups.length" class="muted">暂无数据。</p><ul v-else><li v-for="item in overview.groups" :key="item.groupId">组 #{{ item.groupId }}：活动 {{ item.activeCount }}，处理中 {{ item.processingCount }}，待分配 {{ item.unassignedCount }}</li></ul></article></section></template></template>
<style scoped>.date-filter{display:flex;align-items:end;gap:10px}.date-filter label{margin:0}.metric-grid,.detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:20px}.metric-grid article{background:var(--panel);border:1px solid var(--line);padding:20px;border-radius:12px}.metric-grid span{display:block;color:var(--muted);font-size:13px}.metric-grid strong{display:block;font-size:25px;margin-top:10px}.detail-grid ul{padding-left:20px;margin-bottom:0}.detail-grid li+li{margin-top:8px}@media(max-width:700px){.page-heading{display:block}.date-filter{margin-top:15px;flex-wrap:wrap}.metric-grid,.detail-grid{grid-template-columns:repeat(2,1fr)}}</style>
